window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4ddce450f27d7b30"]={"versions": [{"id": "FIG-4ddce450f27d7b30", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung eines partiellen AUTOSAR-Modellausschnitts und der Differenzerkennung (Model Compare and Merge / Differencing) im Rahmen der Interoperabilität von AUTOSAR-Werkzeugen. Die Farbcodierung (grün hinterlegte Modellinstanzen) markiert geänderte bzw. hinzugefügte Modellelemente und Aggregationen gegenüber einem Ausgangszustand.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellinstanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> mit Attributen <code>uuid = 6</code> und <code>shortName = OEM</code> (grün markiert). Es aggregiert über die Kompositionen <code>+element</code>:</li>\n<li>Ein <code>:SenderReceiverInterface</code> (grün markiert) mit <code>isService = false</code>, <code>shortName = interface</code>.</li>\n<li>Ein <code>:ApplicationPrimitiveDataType</code> mit <code>shortName = velocityType</code>.</li>\n<li>Eine weitere Instanz <code>ApplicationPrimitiveDataType : ApplicationPrimitiveDataType</code> (grün markiert) mit <code>shortName = Boolean</code>.</li>\n<li><code>:SenderReceiverInterface</code> (<code>shortName = interface</code>) aggregiert über <code>+dataElement</code>:</li>\n<li>Den <code>:VariableDataPrototype</code> mit <code>shortName = velocity</code>.</li>\n<li>Den <code>:VariableDataPrototype</code> (grün markiert) mit <code>shortName = buttonPressed</code>.</li>\n<li><code>:VariableDataPrototype</code> (<code>shortName = velocity</code>) referenziert über die gerichtete Assoziation <code>+type</code> den <code>:ApplicationPrimitiveDataType</code> (<code>velocityType</code>).</li>\n<li><code>:VariableDataPrototype</code> (<code>shortName = buttonPressed</code>) referenziert über <code>+type</code> den <code>:ApplicationPrimitiveDataType</code> (<code>Boolean</code>).</li>\n<li><code>:ApplicationPrimitiveDataType</code> (<code>velocityType</code>) aggregiert über Kompositionen:</li>\n<li><code>+invalidValue</code>: <code>:NumericalValueSpecification</code> mit <code>value = 10000</code>.</li>\n<li><code>+displayFormat</code>: <code>:DisplayFormatString</code> mit <code>value = %f6.2</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Instanzdiagramm; es stellt keinen sequenziellen Ablauf oder Laufzeitverhalten dar. Die Struktur dient als Referenz-Instanzgraph für Vergleichs- und Merge-Algorithmen von AUTOSAR-Authoring-Tools bei der Identifikation von Delta-Änderungen auf Element- und Aggregationsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung dient als normatives Anschauungsbeispiel für Werkzeughersteller zur Implementierung von AUTOSAR-Modellvergleichen. Werkzeuge müssen erkennen, dass sowohl hinzugefügte Elemente (<code>buttonPressed</code>, <code>Boolean</code>) als auch die übergeordneten Containerelemente (<code>OEM</code>, <code>interface</code>), deren Aggregationen sich erweitert haben, als modifiziert zu kennzeichnen sind. Attribut- und Namenskonventionen entsprechen den AUTOSAR-M1-Metamodellregeln für Software-Schnittstellen und Datentypen.</p>"}, {"id": "FIG-ce33fa31816f3e20", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) zur Veranschaulichung eines partiellen AUTOSAR-Modellausschnitts und der Differenzerkennung (Model Compare and Merge / Differencing) im Rahmen der Interoperabilität von AUTOSAR-Werkzeugen. Die Farbcodierung (grün hinterlegte Modellinstanzen) markiert geänderte bzw. hinzugefügte Modellelemente und Aggregationen gegenüber einem Ausgangszustand.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellinstanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> mit Attributen <code>uuid = 6</code> und <code>shortName = OEM</code> (grün markiert). Es aggregiert über die Kompositionen <code>+element</code>:</li>\n<li>Ein <code>:SenderReceiverInterface</code> (grün markiert) mit <code>isService = false</code>, <code>shortName = interface</code>.</li>\n<li>Ein <code>:ApplicationPrimitiveDataType</code> mit <code>shortName = velocityType</code>.</li>\n<li>Eine weitere Instanz <code>ApplicationPrimitiveDataType : ApplicationPrimitiveDataType</code> (grün markiert) mit <code>shortName = Boolean</code>.</li>\n<li><code>:SenderReceiverInterface</code> (<code>shortName = interface</code>) aggregiert über <code>+dataElement</code>:</li>\n<li>Den <code>:VariableDataPrototype</code> mit <code>shortName = velocity</code>.</li>\n<li>Den <code>:VariableDataPrototype</code> (grün markiert) mit <code>shortName = buttonPressed</code>.</li>\n<li><code>:VariableDataPrototype</code> (<code>shortName = velocity</code>) referenziert über die gerichtete Assoziation <code>+type</code> den <code>:ApplicationPrimitiveDataType</code> (<code>velocityType</code>).</li>\n<li><code>:VariableDataPrototype</code> (<code>shortName = buttonPressed</code>) referenziert über <code>+type</code> den <code>:ApplicationPrimitiveDataType</code> (<code>Boolean</code>).</li>\n<li><code>:ApplicationPrimitiveDataType</code> (<code>velocityType</code>) aggregiert über Kompositionen:</li>\n<li><code>+invalidValue</code>: <code>:NumericalValueSpecification</code> mit <code>value = 10000</code>.</li>\n<li><code>+displayFormat</code>: <code>:DisplayFormatString</code> mit <code>value = %f6.2</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Instanzdiagramm; es stellt keinen sequenziellen Ablauf oder Laufzeitverhalten dar. Die Struktur dient als Referenz-Instanzgraph für Vergleichs- und Merge-Algorithmen von AUTOSAR-Authoring-Tools bei der Identifikation von Delta-Änderungen auf Element- und Aggregationsebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung dient als normatives Anschauungsbeispiel für Werkzeughersteller zur Implementierung von AUTOSAR-Modellvergleichen. Werkzeuge müssen erkennen, dass sowohl hinzugefügte Elemente (<code>buttonPressed</code>, <code>Boolean</code>) als auch die übergeordneten Containerelemente (<code>OEM</code>, <code>interface</code>), deren Aggregationen sich erweitert haben, als modifiziert zu kennzeichnen sind. Attribut- und Namenskonventionen entsprechen den AUTOSAR-M1-Metamodellregeln für Software-Schnittstellen und Datentypen.</p>"}], "trans": [{"from": "FIG-4ddce450f27d7b30", "to": "FIG-ce33fa31816f3e20", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Im Kopfbereich der Instanz <code>ApplicationPrimitiveDataType</code> (<code>shortName = Boolean</code>) wurde die Zeichenkette <code>ApplicationPrimitiveDataType :</code> typografisch zu <code>ApplicationPrimitiveDataType:</code> bereinigt (Schließen des Leerzeichens vor dem Doppelpunkt).</li>\n<li>Die Pfeilspitze der Assoziation <code>+element</code> vom <code>:ARPackage</code> zum <code>:SenderReceiverInterface</code> wurde minimal im Pixel-Rendering verschoben/angepasst.</li>\n</ul>"}]};
